Let me compute the edges: vertex i: ang = A + i*2π/9; V = (CX + R cos ang, CY + R sin ang).

Inward normal for the edge between V_i and V_{i+1}: M = midpoint; n = (O - M)/|O - M|. For a regular polygon centered at O, this is well defined.

Precompute per substep (9 edges).

substep(h):

```js
function substep(h) {
  const A = OMEGA * simT;
  const vs = [];
  for (let i = 0; i < POLY_N; i++) {
    const a1 = A + i * (2 * Math.PI) / POLY_N;
    const a2 = a1 + (2 * Math.PI) / POLY_N;
    const x1 = CX + POLY_R * Math.cos(a1), y1 = CY + POLY_R * Math.sin(a1);
    const x2 = CX + POLY_R * Math.cos(a2), y2 = CY + POLY_R * Math.sin(a2);
    const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
    let nx = CX - mx, ny = CY - my;
    const len = Math.hypot(nx, ny);
    nx /= len; ny /= len;
    vs.push({ nx, ny, mx, my });
  }

  // Integrate
  const drag = Math.exp(-AIR_K * h);
  const spinDrag = Math.exp(-SPIN_AIR_K * h);
  for (const b of balls) {
    b.vy += GRAVITY * h;
    b.vx *= drag; b.vy *= drag;
    b.x += b.vx * h;
    b.y += b.vy * h;
    b.rot += b.w * h;
    b.w *= spinDrag;
  }

  for (let it = 0; it < ITER; it++) {
    // Ball-wall
    for (const b of balls) {
      for (const e of vs) {
        const d = (b.x - e.mx) * e.nx + (b.y - e.my) * e.ny;
        if (d < b.r) {
          const pen = b.r - d;
          b.x += e.nx * pen;
          b.y += e.ny * pen;
          // Wall velocity at the contact point
          const px = b.x - e.nx * b.r;
          const py = b.y - e.ny * b.r;
          const wx = -OMEGA * (py - CY);
          const wy = OMEGA * (px - CX);
          let rvx = b.vx - wx, rvy = b.vy - wy;
          const vn = rvx * e.nx + rvy * e.ny;
          if (vn < 0) {
            const j = -(1 + REST) * vn;
            b.vx += j * e.nx;
            b.vy += j * e.ny;
            rvx = b.vx - wx; rvy = b.vy - wy;
            const tx = -e.ny, ty = e.nx;
            const s = rvx * tx + rvy * ty;
            if (Math.abs(s) > 1e-9) {
              const f = s * WALL_FRICTION;
              b.vx -= f * tx;
              b.vy -= f * ty;
              b.w += (s / b.r - b.w) * WALL_SPIN;
            }
          }
        }
      }
    }
    // Ball-ball
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i], c = balls[j];
        let dx = c.x - a.x, dy = c.y - a.y;
        let dist = Math.hypot(dx, dy);
        const minD = a.r + c.r;
        if (dist >= minD) continue;
        if (dist < 1e-6) { dx = 1; dy = 0; dist = 1; }
        const nx = dx / dist, ny = dy / dist;
        const pen = minD - dist;
        a.x -= nx * pen / 2; a.y -= ny * pen / 2;
        c.x += nx * pen / 2; c.y += ny * pen / 2;
        const rvx = a.vx - c.vx, rvy = a.vy - c.vy;
        const vn = rvx * nx + rvy * ny;
        if (vn > 0) {
          const jimp = (1 + REST) * vn / 2;
          a.vx -= jimp * nx; a.vy -= jimp * ny;
          c.vx += jimp * nx; c.vy += jimp * ny;
          const tx = -ny, ty = nx;
          const s = (a.vx - c.vx) * tx + (a.vy - c.vy) * ty;
          if (Math.abs(s) > 1e-9) {
            const f = s * BALL_FRICTION / 2;
            a.vx -= f * tx; a.vy -= f * ty;
            c.vx += f * tx; c.vy += f * ty;
          }
        }
      }
    }
  }

  // Final hard projection
  for (const b of balls) {
    for (const e of vs) {
      const d = (b.x - e.mx) * e.nx + (b.y - e.my) * e.ny;
      if (d < b.r) {
        const pen = b.r - d;
        b.x += e.nx * pen; b.y += e.ny * pen;
        const vn = b.vx * e.nx + b.vy * e.ny;
        if (vn < 0) { b.vx -= vn * e.nx; b.vy -= vn * e.ny; }
      }
    }
  }
}
```

