      const mx = (x1+x2)/2, my = (y1+y2)/2;
      let nx = cx-mx, ny = cy-my;
      const L = Math.hypot(nx, ny);
      nx /= L; ny /= L;
      const d = (b.x-mx)*nx + (b.y-my)*ny;
