(function () {
  "use strict";

  var canvas = document.getElementById("c");
  var ctx = null;
  if (canvas && typeof canvas.getContext === "function") {
    try { ctx = canvas.getContext("2d"); } catch (e) { ctx = null; }
  }

  var W = 700, H = 700;
  var CX = W / 2, CY = H / 2;

  var POLY_N = 9;
  var POLY_R = 260;
  var PERIOD = 7;
  var OMEGA = (2 * Math.PI) / PERIOD;
  var BALL_R = 14;
  var NUM_BALLS = 13;

  var GRAVITY = 500;
  var AIR_K = 0.08;
  var SPIN_AIR_K = 0.1;
  var REST = 0.82;
  var WALL_FRICTION = 0.12;
  var WALL_SPIN = 0.35;
  var BALL_FRICTION = 0.1;
  var SUBDT = 1 / 240;
  var ITER = 10;
  var GUARD = 6;
  var STEP = (2 * Math.PI) / POLY_N;

  var balls = [];
  for (var i = 0; i < NUM_BALLS; i++) {
    var a = -Math.PI / 2 + i * (2 * Math.PI) / NUM_BALLS;
    balls.push({
      id: i,
      x: CX + Math.cos(a) * 62,
      y: CY + Math.sin(a) * 62,
      vx: 0,
      vy: 0,
      r: BALL_R,
      rot: (i * Math.PI) / 5,
      w: 0,
      hue: Math.round((i * 360) / NUM_BALLS)
    });
  }

  var simT = 0;
  var manual = false;

  function edges() {
    var A = OMEGA * simT;
    var list = [];
    for (var i = 0; i < POLY_N; i++) {
      var x1 = CX + POLY_R * Math.cos(A + i * STEP);
      var y1 = CY + POLY_R * Math.sin(A + i * STEP);
      var x2 = CX + POLY_R * Math.cos(A + (i + 1) * STEP);
      var y2 = CY + POLY_R * Math.sin(A + (i + 1) * STEP);
      var mx = (x1 + x2) / 2;
      var my = (y1 + y2) / 2;
      var nx = CX - mx;
      var ny = CY - my;
      var len = Math.sqrt(nx * nx + ny * ny);
      list.push({ nx: nx / len, ny: ny / len, mx: mx, my: my });
    }
    return list;
  }

  function resolveWall(b, e) {
    var d = (b.x - e.mx) * e.nx + (b.y - e.my) * e.ny;
    if (d >= b.r) return;
    b.x += e.nx * (b.r - d);
    b.y += e.ny * (b.r - d);
    var px = b.x - e.nx * b.r;
    var py = b.y - e.ny * b.r;
    var wx = -OMEGA * (py - CY);
    var wy = OMEGA * (px - CX);
    var rvx = b.vx - wx;
    var rvy = b.vy - wy;
    var vn = rvx * e.nx + rvy * e.ny;
    if (vn < 0) {
      var j = -(1 + REST) * vn;
      b.vx += j * e.nx;
      b.vy += j * e.ny;
      var tx = -e.ny;
      var ty = e.nx;
      var s = (b.vx - wx) * tx + (b.vy - wy) * ty;
      if (s > 1e-9 || s < -1e-9) {
        b.vx -= s * WALL_FRICTION * tx;
        b.vy -= s * WALL_FRICTION * ty;
        b.w += (s / b.r - b.w) * WALL_SPIN;
      }
    }
  }

  function separatePair(p, q) {
    var dx = q.x - p.x;
    var dy = q.y - p.y;
    var dist = Math.sqrt(dx * dx + dy * dy);
    var minD = p.r + q.r;
    if (dist >= minD) return;
    var nx, ny;
    if (dist < 1e-9) { nx = 1; ny = 0; dist = 1; }
    else { nx = dx / dist; ny = dy / dist; }
    var pen = (minD - dist) / 2;
    p.x -= nx * pen;
    p.y -= ny * pen;
    q.x += nx * pen;
    q.y += ny * pen;
    var rvx = p.vx - q.vx;
    var rvy = p.vy - q.vy;
    var vn = rvx * nx + rvy * ny;
    if (vn > 0) {
      var j = (1 + REST) * vn / 2;
      p.vx -= j * nx;
      p.vy -= j * ny;
      q.vx += j * nx;
      q.vy += j * ny;
      var tx = -ny;
      var ty = nx;
      var s = (p.vx - q.vx) * tx + (p.vy - q.vy) * ty;
      if (s > 1e-9 || s < -1e-9) {
        var f = s * BALL_FRICTION / 2;
        p.vx -= f * tx;
        p.vy -= f * ty;
        q.vx += f * tx;
        q.vy += f * ty;
        p.w += (-s / (2 * p.r) - p.w) * 0.08;
        q.w += (-s / (2 * q.r) - q.w) * 0.08;
      }
    }
  }

  function substep(h) {
    var es = edges();
    var drag = Math.exp(-AIR_K * h);
    var sdrag = Math.exp(-SPIN_AIR_K * h);
    for (var i = 0; i < balls.length; i++) {
      var b = balls[i];
      b.vy += GRAVITY * h;
      b.vx *= drag;
      b.vy *= drag;
      b.x += b.vx * h;
      b.y += b.vy * h;
      b.rot += b.w * h;
      b.w *= sdrag;
    }
    for (var it = 0; it < ITER; it++) {
      for (var i = 0; i < balls.length; i++) {
        for (var e = 0; e < es.length; e++) resolveWall(balls[i], es[e]);
      }
      for (var i = 0; i < balls.length; i++) {
        for (var j = i + 1; j < balls.length; j++) separatePair(balls[i], balls[j]);
      }
    }
    for (var g = 0; g < GUARD; g++) {
      for (var i = 0; i < balls.length; i++) {
        for (var j = i + 1; j < balls.length; j++) {
          var p = balls[i], q = balls[j];
          var dx = q.x - p.x;
          var dy = q.y - p.y;
          var dist = Math.sqrt(dx * dx + dy * dy);
          var minD = p.r + q.r;
          if (dist >= minD) continue;
          var nx = 1, ny = 0;
          if (dist > 1e-9) { nx = dx / dist; ny = dy / dist; }
          var pen = (minD - dist) / 2;
          p.x -= nx * pen; p.y -= ny * pen;
          q.x += nx * pen; q.y += ny * pen;
        }
      }
      for (var i = 0; i < balls.length; i++) {
        var b = balls[i];
        for (var e = 0; e < es.length; e++) {
          var ed = es[e];
          var d = (b.x - ed.mx) * ed.nx + (b.y - ed.my) * ed.ny;
          if (d < b.r) {
            b.x += ed.nx * (b.r - d);
            b.y += ed.ny * (b.r - d);
          }
        }
      }
    }
  }

  function advance(dt) {
    var remaining = Math.max(0, dt);
    while (remaining > 1e-9) {
      var h = Math.min(SUBDT, remaining);
      substep(h);
      simT += h;
      remaining -= h;
    }
  }

  function render() { ... }

  var lastNow = null;
  function frame(now) {
    if (manual) return;
    if (lastNow === null) lastNow = now;
    var dt = (now - lastNow) / 1000;
    lastNow = now;
    if (dt < 0) dt = 0;
    if (dt > 0.05) dt = 0.05;
    advance(dt);
    render();
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(frame);
  }

  if (typeof requestAnimationFrame === "function") requestAnimationFrame(frame);
  render();

  window.__bench = {
    getState: function () {
      return {
        t: simT,
        poly: {
          n: POLY_N,
          radius: POLY_R,
          cx: CX,
          cy: CY,
          angle: OMEGA * simT,
          periodSec: PERIOD
        },
        balls: balls.map(function (b) {
          return { id: b.id, x: b.x, y: b.y, r: b.r, vx: b.vx, vy: b.vy };
        })
      };
    },
    step: function (dtSeconds) {
      manual = true;
      advance(dtSeconds || 0);
      render();
    }
  };
})();
